export const meta = { name: 'p', description: 'd' }
const out = {}
const attempt = async (name, f) => { try { const v = await f(); out[name] = 'ok: ' + (JSON.stringify(v) ?? String(v)).slice(0, 120) } catch (e) { out[name] = 'threw ' + (e && e.constructor && e.constructor.name) + ': ' + String(e && e.message).slice(0, 300) } }
await attempt('parallel values', () => parallel([1, Promise.resolve(2)]))
await attempt('parallel string', () => parallel('ab'))
await attempt('parallel nothing', () => parallel())
await attempt('parallel empty', () => parallel([]))
await attempt('parallel thunk throws', () => parallel([() => { throw new Error('x') }, () => 2, async () => { throw new Error('y') }]))
await attempt('parallel 4096', async () => (await parallel(Array.from({ length: 4096 }, () => () => 1))).length)
await attempt('parallel 4097', async () => (await parallel(Array.from({ length: 4097 }, () => () => 1))).length)
await attempt('pipeline no stage', () => pipeline([1, 2]))
await attempt('pipeline string items', () => pipeline('ab', (v) => v))
await attempt('pipeline stage not function', () => pipeline([1], 'x'))
await attempt('pipeline stage args', () => pipeline(['a', 'b'], (v) => v + '1', (previous, item, index) => [previous, item, index].join('|')))
await attempt('pipeline stage throws', () => pipeline([1, 2], (v) => { if (v === 1) throw new Error('x'); return v }, (v) => v * 10))
await attempt('pipeline 4097', async () => (await pipeline(Array.from({ length: 4097 }, () => 1), (v) => v)).length)
await attempt('phase number', () => phase(5))
await attempt('phase nothing', () => phase())
await attempt('phase unknown title', () => phase('Not in meta'))
await attempt('phase object', () => phase({ title: 'x' }))
await attempt('log nothing', () => log())
await attempt('log object', () => log({ a: 1 }))
await attempt('log two arguments', () => log('a', 'b'))
await attempt('log long line', () => log('x'.repeat(20000)))
await attempt('console.log', () => console.log('from console', { a: 1 }))
await attempt('workflow number', () => workflow(5))
await attempt('workflow unknown name', () => workflow('no-such-workflow-name-xyz'))
await attempt('workflow missing path', () => workflow({ scriptPath: args.dir + '/missing.js' }))
await attempt('workflow nested', () => workflow({ scriptPath: args.dir + '/cases/c09-top-level-await.js' }))
return out
